from hypothesis import given, strategies as st
import pytest


def flatten_iter(iterable):
    """``flatten_iter()`` yields all the elements from *iterable* while
    collapsing any nested iterables.

    >>> nested = [[1, 2], [[3], [4, 5]]]
    >>> list(flatten_iter(nested))
    [1, 2, 3, 4, 5]
    """
    from collections.abc import Iterable
    for item in iterable:
        if isinstance(item, Iterable) and (not isinstance(item, (str, bytes))):
            yield from flatten_iter(item)
        else:
            yield item


@given(iterable=st.recursive(st.integers() | st.text(max_size=5) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_idempotence(iterable):
    first = list(flatten_iter(iterable))
    second = list(flatten_iter(first))
    assert second == first


@given(iterable=st.recursive(st.integers() | st.text(max_size=5) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_invariant_preservation(iterable):
    def all_leaf_elements(x):
        from collections.abc import Iterable
        result = []
        for item in x:
            if isinstance(item, Iterable) and not isinstance(item, (str, bytes)):
                result.extend(all_leaf_elements(item))
            else:
                result.append(item)
        return result
    def sort_key(v):
        return (str(type(v)), str(v))
    assert sorted(flatten_iter(iterable), key=sort_key) == sorted(all_leaf_elements(iterable), key=sort_key)


@given(a=st.recursive(st.integers() | st.text(max_size=5) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20), b=st.recursive(st.integers() | st.text(max_size=5) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_metamorphic(a, b):
    combined = list(flatten_iter([a, b]))
    separate = list(flatten_iter(a)) + list(flatten_iter(b))
    assert combined == separate


@given(iterable=st.recursive(st.integers() | st.text(max_size=5) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_type_postcondition(iterable):
    result = flatten_iter(iterable)
    assert hasattr(result, '__iter__')
    materialized = list(result)
    assert all(not isinstance(x, (list, tuple, set)) for x in materialized)


@given(iterable=st.recursive(st.integers() | st.text(max_size=5) | st.booleans() | st.none(), lambda children: st.lists(children, max_size=5) | st.tuples(children, children), max_leaves=20))
def test_totality(iterable):
    result = list(flatten_iter(iterable))
    assert isinstance(result, list)

from hypothesis import given, strategies as st
import pytest


def ceil(x, options=None):
    """Return the ceiling of *x*. If *options* is set, return the smallest
    integer or float from *options* that is greater than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> ceil(3.5, options=VALID_CABLE_CSA)
    4
    >>> ceil(4, options=VALID_CABLE_CSA)
    4
    """
    from math import ceil as _ceil
    import bisect
    if options is None:
        return _ceil(x)
    options = sorted(options)
    i = bisect.bisect_left(options, x)
    if i == len(options):
        raise ValueError('no ceil options greater than or equal to: %r' % x)
    return options[i]


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_value_postcondition(x):
    assert ceil(x) >= x


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_value_postcondition_2(x, options):
    max_option = max(options)
    if x <= max_option:
        result = ceil(x, options=options)
        assert result in options
        assert result >= x


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_idempotence(x):
    assert ceil(ceil(x)) == ceil(x)


@given(x=st.integers(min_value=-10**6, max_value=10**6))
def test_metamorphic(x):
    assert ceil(x) == x


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_value_postcondition_3(x):
    assert ceil(x) - x < 1


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_totality(x):
    ceil(x)

from hypothesis import given, strategies as st
import pytest


def subdict(d, keep=None, drop=None):
    """Compute the "subdictionary" of a dict, *d*.

    A subdict is to a dict what a subset is a to set. If *A* is a
    subdict of *B*, that means that all keys of *A* are present in
    *B*.

    Returns a new dict with any keys in *drop* removed, and any keys
    in *keep* still present, provided they were in the original
    dict. *keep* defaults to all keys, *drop* defaults to empty, so
    without one of these arguments, calling this function is
    equivalent to calling ``dict()``.

    >>> from pprint import pprint as pp
    >>> pp(subdict({'a': 1, 'b': 2}))
    {'a': 1, 'b': 2}
    >>> subdict({'a': 1, 'b': 2, 'c': 3}, drop=['b', 'c'])
    {'a': 1}
    >>> pp(subdict({'a': 1, 'b': 2, 'c': 3}, keep=['a', 'c']))
    {'a': 1, 'c': 3}

    """
    if keep is None:
        keep = d.keys()
    if drop is None:
        drop = []
    keys = set(keep) - set(drop)
    return type(d)([(k, v) for k, v in d.items() if k in keys])


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers(), max_size=8), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)))
def test_invariant_preservation(d, keep):
    result = subdict(d, keep=keep)
    assert set(result.keys()).issubset(set(d.keys()))
    assert all(result[key] == d[key] for key in result)


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers(), max_size=8), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)))
def test_idempotence(d, keep, drop):
    first = subdict(d, keep=keep, drop=drop)
    second = subdict(first, keep=keep, drop=drop)
    assert second == first


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers(), max_size=8), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)))
def test_metamorphic(d, drop):
    drop_keys = drop if drop is not None else []
    assert subdict(d, drop=drop_keys) == subdict(d, keep=set(d.keys()) - set(drop_keys))


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers(), max_size=8), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)))
def test_value_postcondition(d, keep, drop):
    result = subdict(d, keep=keep, drop=drop)
    expected = (set(keep if keep is not None else d.keys()) - set(drop if drop is not None else [])) & set(d.keys())
    assert set(result.keys()) == expected


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers(), max_size=8), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)))
def test_type_postcondition(d, keep, drop):
    assert type(subdict(d, keep=keep, drop=drop)) == type(d)


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers(), max_size=8), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5), max_size=8, unique=True)))
def test_totality(d, keep, drop):
    subdict(d, keep=keep, drop=drop)

from hypothesis import given, strategies as st
import pytest


def construct_format_field_str(fname, fspec, conv):
    """
    Constructs a format field string from the field name, spec, and
    conversion character (``fname``, ``fspec``, ``conv``). See Python
    String Formatting for more info.
    """
    if fname is None:
        return ''
    ret = '{' + fname
    if conv:
        ret += '!' + conv
    if fspec:
        ret += ':' + fspec
    ret += '}'
    return ret


@given(fname=st.one_of(st.none(), st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), max_codepoint=127), min_size=0, max_size=10)), fspec=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), max_codepoint=127), min_size=0, max_size=10), conv=st.one_of(st.none(), st.sampled_from(['r', 's', 'a'])))
def test_type_postcondition(fname, fspec, conv):
    assert isinstance(construct_format_field_str(fname, fspec, conv), str)


