from hypothesis import given, strategies as st
import pytest


def format_invocation(name='', args=(), kwargs=None, **kw):
    """Given a name, positional arguments, and keyword arguments, format
    a basic Python-style function call.

    >>> print(format_invocation('func', args=(1, 2), kwargs={'c': 3}))
    func(1, 2, c=3)
    >>> print(format_invocation('a_func', args=(1,)))
    a_func(1)
    >>> print(format_invocation('kw_func', kwargs=[('a', 1), ('b', 2)]))
    kw_func(a=1, b=2)

    """
    _repr = kw.pop('repr', repr)
    if kw:
        raise TypeError('unexpected keyword args: %r' % ', '.join(kw.keys()))
    kwargs = kwargs or {}
    a_text = ', '.join([_repr(a) for a in args])
    if isinstance(kwargs, dict):
        kwarg_items = [(k, kwargs[k]) for k in sorted(kwargs)]
    else:
        kwarg_items = kwargs
    kw_text = ', '.join([f'{k}={_repr(v)}' for k, v in kwarg_items])
    all_args_text = a_text
    if all_args_text and kw_text:
        all_args_text += ', '
    all_args_text += kw_text
    return f'{name}({all_args_text})'


@given(name=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu')), min_size=1, max_size=20), args=st.lists(st.one_of(st.integers(), st.text(max_size=10), st.floats(allow_nan=False), st.booleans()), max_size=5).map(tuple), kwargs=st.one_of(st.none(), st.dictionaries(st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu')), min_size=1, max_size=10), st.one_of(st.integers(), st.text(max_size=10), st.floats(allow_nan=False), st.booleans())), st.lists(st.tuples(st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu')), min_size=1, max_size=10), st.one_of(st.integers(), st.text(max_size=10), st.floats(allow_nan=False), st.booleans())), max_size=5)))
def test_type_postcondition(name, args, kwargs):
    assert isinstance(format_invocation(name, args=args, kwargs=kwargs), str)


@given(name=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu')), min_size=1, max_size=20), k=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu')), min_size=1, max_size=10), v=st.one_of(st.integers(), st.text(max_size=10), st.floats(allow_nan=False), st.booleans()))
