from hypothesis import given, strategies as st
import pytest
import sys
import types


def get_module_callables(mod, ignore=None):
    """Returns two maps of (*types*, *funcs*) from *mod*, optionally
    ignoring based on the :class:`bool` return value of the *ignore*
    callable. *mod* can be a string name of a module in
    :data:`sys.modules` or the module instance itself.
    """
    import sys
    if isinstance(mod, str):
        mod = sys.modules[mod]
    types, funcs = ({}, {})
    for attr_name in dir(mod):
        if ignore and ignore(attr_name):
            continue
        try:
            attr = getattr(mod, attr_name)
        except Exception:
            continue
        try:
            attr_mod_name = attr.__module__
        except AttributeError:
            continue
        if attr_mod_name != mod.__name__:
            continue
        if isinstance(attr, type):
            types[attr_name] = attr
        elif callable(attr):
            funcs[attr_name] = attr
    return (types, funcs)


@given(mod=st.sampled_from(sorted([name for name, m in list(sys.modules.items()) if m is not None])))
def test_type_postcondition(mod):
    types, funcs = get_module_callables(mod)
    assert isinstance(types, dict) and isinstance(funcs, dict)
    assert all(isinstance(k, str) and isinstance(v, type) for k, v in types.items())
    assert all(isinstance(k, str) and callable(v) for k, v in funcs.items())


@given(mod=st.sampled_from(sorted([name for name, m in list(sys.modules.items()) if m is not None])))
def test_invariant_preservation(mod):
    types, funcs = get_module_callables(mod)
    m = sys.modules[mod] if isinstance(mod, str) else mod
    assert set(types) & set(funcs) == set()
    assert all(name in dir(m) for name in {**types, **funcs})


@given(mod=st.sampled_from(sorted([name for name, m in list(sys.modules.items()) if m is not None])))
def test_metamorphic(mod):
    assert get_module_callables(mod, ignore=lambda n: True) == ({}, {})


@given(mod=st.sampled_from(sorted([name for name, m in list(sys.modules.items()) if m is not None])), ignore=st.one_of(st.none(), st.just(lambda n: False), st.just(lambda n: True), st.just(lambda n: n.startswith('_'))))
def test_totality(mod, ignore):
    get_module_callables(mod, ignore=ignore)

