def test_value_postcondition_bounds(stop, start, step):
    result = frange(stop, start, step)
    real_start = 0.0 if start is None else start
    real_stop = stop
    if start is not None:
        real_start, real_stop = start * 1.0, stop * 1.0
    if step > 0:
        assert all(real_start <= x < real_stop for x in result)
    else:
        assert all(real_stop < x <= real_start for x in result)


@given(stop=st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=-100, max_value=100, allow_nan=False, allow_infinity=False).filter(lambda x: x != 0))
