@given(stop=st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False), start=st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False), step=st.floats(min_value=-100, max_value=100, allow_nan=False, allow_infinity=False).filter(lambda x: x != 0))
