from hypothesis import given, strategies as st
import pytest


def rstrip_iter(iterable, strip_value=None):
    """Strips values from the end of an iterable. Stripped items will
    match the value of the argument strip_value. Functionality is analogous
    to that of the method str.rstrip. Returns a generator.

    >>> list(rstrip_iter(['Foo', 'Bar', 'Bam'], 'Bam'))
    ['Foo', 'Bar']

    """
    iterator = iter(iterable)
    for i in iterator:
        if i == strip_value:
            cache = list()
            cache.append(i)
            broken = False
            for i in iterator:
                if i == strip_value:
                    cache.append(i)
                else:
                    broken = True
                    break
            if not broken:
                return
            yield from cache
        yield i


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_idempotence(iterable, strip_value):
    first = list(rstrip_iter(iterable, strip_value))
    second = list(rstrip_iter(first, strip_value))
    assert second == first


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_invariant_preservation(iterable, strip_value):
    result = list(rstrip_iter(iterable, strip_value))
    assert len(result) <= len(iterable)
    assert iterable[:len(result)] == result


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_metamorphic(iterable, strip_value):
    assert list(rstrip_iter(iterable + [strip_value], strip_value)) == list(rstrip_iter(iterable, strip_value))


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_value_postcondition(iterable, strip_value):
    result = list(rstrip_iter(iterable, strip_value))
    assert not result or result[-1] != strip_value


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_type_postcondition(iterable, strip_value):
    gen = rstrip_iter(iterable, strip_value)
    assert hasattr(gen, '__iter__') and hasattr(gen, '__next__')


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_totality(iterable, strip_value):
    result = list(rstrip_iter(iterable, strip_value))
    assert isinstance(result, list)

from hypothesis import given, strategies as st
import pytest
from boltons.mathutils import frange


def xfrange(stop, start=None, step=1.0):
    """Same as :func:`frange`, but generator-based instead of returning a
    list.

    >>> tuple(xfrange(1, 3, step=0.75))
    (1.0, 1.75, 2.5)

    See :func:`frange` for more details.
    """
    if not step:
        raise ValueError('step must be non-zero')
    if start is None:
        start, stop = (0.0, stop * 1.0)
    else:
        stop, start = (start * 1.0, stop * 1.0)
    cur = start
    while cur < stop:
        yield cur
        cur += step


@given(stop=st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=100, allow_nan=False, allow_infinity=False) | st.floats(min_value=-100, max_value=-0.01, allow_nan=False, allow_infinity=False))
def test_value_postcondition(stop, start, step):
    if step <= 0:
        return
    values = list(xfrange(stop, start, step))
    if start is None:
        lo, hi = 0.0, stop * 1.0
    else:
        lo, hi = start * 1.0, stop * 1.0
    assert all(lo <= x < hi for x in values)


@given(stop=st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=100, allow_nan=False, allow_infinity=False) | st.floats(min_value=-100, max_value=-0.01, allow_nan=False, allow_infinity=False))
def test_metamorphic(stop, start, step):
    values = list(xfrange(stop, start, step))
    if step > 0:
        assert all(a < b for a, b in zip(values, values[1:]))
    else:
        assert all(a > b for a, b in zip(values, values[1:]))


@given(stop=st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=100, allow_nan=False, allow_infinity=False) | st.floats(min_value=-100, max_value=-0.01, allow_nan=False, allow_infinity=False))
def test_invariant_preservation(stop, start, step):
    xf_values = list(xfrange(stop, start, step))
    fr_values = frange(stop, start, step)
    assert len(xf_values) == len(fr_values)


@given(stop=st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False), start=st.one_of(st.none(), st.floats(min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False)), step=st.floats(min_value=0.01, max_value=100, allow_nan=False, allow_infinity=False) | st.floats(min_value=-100, max_value=-0.01, allow_nan=False, allow_infinity=False))
def test_totality(stop, start, step):
    list(xfrange(stop, start, step))

from hypothesis import given, strategies as st
import pytest


def clamp(x, lower=float('-inf'), upper=float('inf')):
    """Limit a value to a given range.

    Args:
        x (int or float): Number to be clamped.
        lower (int or float): Minimum value for x.
        upper (int or float): Maximum value for x.

    The returned value is guaranteed to be between *lower* and
    *upper*. Integers, floats, and other comparable types can be
    mixed.

    >>> clamp(1.0, 0, 5)
    1.0
    >>> clamp(-1.0, 0, 5)
    0
    >>> clamp(101.0, 0, 5)
    5
    >>> clamp(123, upper=5)
    5

    Similar to `numpy's clip`_ function.

    .. _numpy's clip: http://docs.scipy.org/doc/numpy/reference/generated/numpy.clip.html

    """
    if upper < lower:
        raise ValueError('expected upper bound (%r) >= lower bound (%r)' % (upper, lower))
    return min(max(x, lower), upper)


@given(x=st.floats(allow_nan=False), lower=st.floats(allow_nan=False, allow_infinity=True), upper=st.floats(allow_nan=False, allow_infinity=True))
def test_value_postcondition(x, lower, upper):
    if lower <= upper:
        result = clamp(x, lower, upper)
        assert lower <= result <= upper


@given(x=st.floats(allow_nan=False), lower=st.floats(allow_nan=False, allow_infinity=True), upper=st.floats(allow_nan=False, allow_infinity=True))
def test_idempotence(x, lower, upper):
    if lower <= upper:
        once = clamp(x, lower, upper)
        twice = clamp(once, lower, upper)
        assert twice == pytest.approx(once)


