from hypothesis import given, strategies as st
import pytest
from hypothesis import assume


def floor(x, options=None):
    """Return the floor of *x*. If *options* is set, return the largest
    integer or float from *options* that is less than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> floor(3.5, options=VALID_CABLE_CSA)
    2.5
    >>> floor(2.5, options=VALID_CABLE_CSA)
    2.5

    """
    from math import floor as _floor
    import bisect
    if options is None:
        return _floor(x)
    options = sorted(options)
    i = bisect.bisect_right(options, x)
    if not i:
        raise ValueError('no floor options less than or equal to: %r' % x)
    return options[i - 1]


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_value_postcondition(x):
    assert floor(x) <= x


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_value_postcondition_2(x, options):
    try:
        result = floor(x, options)
    except ValueError:
        assume(min(options) > x)
    else:
        assert result <= x
        assert result in options


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_idempotence(x):
    assert floor(floor(x)) == floor(x)


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_metamorphic(x, options):
    try:
        result_forward = floor(x, options)
    except ValueError:
        result_forward = None
    try:
        result_reversed = floor(x, sorted(options, reverse=True))
    except ValueError:
        result_reversed = None
    assert result_forward == result_reversed


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
