from hypothesis import given, strategies as st
import pytest


def format_int_list(int_list, delim=',', range_delim='-', delim_space=False):
    """Returns a sorted range string from a list of positive integers
    (*int_list*). Contiguous ranges of integers are collapsed to min
    and max values. Reverse of :func:`parse_int_list`.

    Args:
        int_list (list): List of positive integers to be converted
           into a range string (e.g. [1,2,4,5,6,8]).
        delim (char): Defaults to ','. Separates integers and
           contiguous ranges of integers.
        range_delim (char): Defaults to '-'. Indicates a contiguous
           range of integers.
        delim_space (bool): Defaults to ``False``. If ``True``, adds a
           space after all *delim* characters.

    >>> format_int_list([1,3,5,6,7,8,10,11,15])
    '1,3,5-8,10-11,15'

    """
    import collections
    output = []
    contig_range = collections.deque()
    for x in sorted(int_list):
        if len(contig_range) < 1:
            contig_range.append(x)
        elif len(contig_range) > 1:
            delta = x - contig_range[-1]
            if delta == 1:
                contig_range.append(x)
            elif delta > 1:
                range_substr = '{:d}{}{:d}'.format(min(contig_range), range_delim, max(contig_range))
                output.append(range_substr)
                contig_range.clear()
                contig_range.append(x)
            else:
                continue
        else:
            delta = x - contig_range[0]
            if delta == 1:
                contig_range.append(x)
            elif delta > 1:
                output.append(f'{contig_range.popleft():d}')
                contig_range.append(x)
            else:
                continue
    else:
        if len(contig_range) == 1:
            output.append(f'{contig_range.popleft():d}')
            contig_range.clear()
        elif len(contig_range) > 1:
            range_substr = '{:d}{}{:d}'.format(min(contig_range), range_delim, max(contig_range))
            output.append(range_substr)
            contig_range.clear()
    if delim_space:
        output_str = (delim + ' ').join(output)
    else:
        output_str = delim.join(output)
    return output_str


@given(int_list=st.lists(st.integers(min_value=1, max_value=1000)))
def test_type_postcondition(int_list):
    assert isinstance(format_int_list(int_list), str)


@given(int_list=st.lists(st.integers(min_value=1, max_value=1000)))
def test_metamorphic(int_list):
    a = format_int_list(int_list)
    b = format_int_list(list(reversed(int_list)))
    c = format_int_list(sorted(int_list))
    assert a == b == c


@given(int_list=st.lists(st.integers(min_value=1, max_value=1000)))
def test_totality(int_list):
    format_int_list(int_list)

from hypothesis import given, strategies as st
import pytest


def human_readable_list(items: typing.Sequence[str], delimiter: str=',', conjunction: str='and', *, oxford: bool=True) -> str:
    """
    Given a list of strings, return a human readable string with
    appropriate delimiters and the conjunction word.

    Args:
        items: The list of strings to join.
        delimiter (optional): The delimiter to use between items.
        conjunction (optional): The word to use before the last item.
        oxford (optional): Whether to use the Oxford comma/delimiter before
            the conjunction in lists of 3+ items.

    Returns:
        str: The human readable string.
    """
    if not items:
        return ''
    delimiter = delimiter and delimiter.strip() + ' '
    conjunction = conjunction.strip()
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f'{items[0]} {conjunction} {items[1]}'
    return f'{delimiter.join(items[:-1])}{(delimiter if oxford else ' ')}{conjunction} {items[-1]}'


@given(items=st.lists(st.text()))
def test_type_postcondition(items):
    assert isinstance(human_readable_list(items), str)


@given(items=st.lists(st.text(), min_size=1))
