    result = human_readable_list(items)
    assert all(item in result for item in items)


def test_value_postcondition_2():
    assert human_readable_list([]) == ''


@given(items=st.lists(st.text(), min_size=2), conjunction=st.text(min_size=1, max_size=10))
def test_metamorphic(items, conjunction):
    assert conjunction in human_readable_list(items, conjunction=conjunction)


@given(items=st.lists(st.text()), delimiter=st.text(min_size=1, max_size=3), conjunction=st.text(min_size=1, max_size=10), oxford=st.booleans())
def test_totality(items, delimiter, conjunction, oxford):
    human_readable_list(items, delimiter, conjunction, oxford=oxford)

