from hypothesis import given, strategies as st
import pytest


def parse_int_list(range_string, delim=',', range_delim='-'):
    """Returns a sorted list of positive integers based on
    *range_string*. Reverse of :func:`format_int_list`.

    Args:
        range_string (str): String of comma separated positive
            integers or ranges (e.g. '1,2,4-6,8'). Typical of a custom
            page range string used in printer dialogs.
        delim (char): Defaults to ','. Separates integers and
            contiguous ranges of integers.
        range_delim (char): Defaults to '-'. Indicates a contiguous
            range of integers.

    >>> parse_int_list('1,3,5-8,10-11,15')
    [1, 3, 5, 6, 7, 8, 10, 11, 15]

    """
    output = []
    for x in range_string.strip().split(delim):
        if range_delim in x:
            range_limits = list(map(int, x.split(range_delim)))
            output += list(range(min(range_limits), max(range_limits) + 1))
        elif not x:
            continue
        else:
            output.append(int(x))
    return sorted(output)


@given(range_string=st.lists(st.one_of(st.integers(min_value=1, max_value=1000).map(str), st.tuples(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000)).map(lambda t: f'{min(t)}-{max(t)}')), min_size=1, max_size=15).map(lambda parts: ','.join(parts)), delim=st.just(','), range_delim=st.just('-'))
def test_idempotence(range_string, delim, range_delim):
    first = parse_int_list(range_string, delim, range_delim)
    second = parse_int_list(delim.join(map(str, first)), delim, range_delim)
    assert second == first


@given(range_string=st.lists(st.one_of(st.integers(min_value=1, max_value=1000).map(str), st.tuples(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000)).map(lambda t: f'{min(t)}-{max(t)}')), min_size=1, max_size=15).map(lambda parts: ','.join(parts)), delim=st.just(','), range_delim=st.just('-'))
def test_value_postcondition(range_string, delim, range_delim):
    result = parse_int_list(range_string, delim, range_delim)
    assert result == sorted(result)
    assert all(isinstance(i, int) and i > 0 for i in result)


@given(range_string=st.lists(st.one_of(st.integers(min_value=1, max_value=1000).map(str), st.tuples(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000)).map(lambda t: f'{min(t)}-{max(t)}')), min_size=1, max_size=15).map(lambda parts: ','.join(parts)), delim=st.just(','), range_delim=st.just('-'))
